  [273845] = { "Questa fiala è stata intagliata con cura meticolosa da uno dei vicini cristalli di cenere vile, che le dà una pallida sfumatura verdastra. Quando la luce la colpisce, sembra che nelle sue pareti cristalline sia intrappolata della cenere che brilla debolmente di energia vile.", 0x368ac42a, "u" },
